namespace Commerce;

public sealed class ShoppingCart
{
    private readonly List<(string Sku, decimal Price, int Qty)> _items = new();
    private readonly Dictionary<string, decimal> _promoCodes = new(StringComparer.OrdinalIgnoreCase)
    {
        ["SAVE10"] = 0.10m,
        ["SAVE20"] = 0.20m,
        ["HALF"] = 0.50m,
    };

    private decimal _discount;

    public IReadOnlyList<(string Sku, decimal Price, int Qty)> Items => _items;

    public void AddItem(string sku, decimal price, int qty)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(price);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(qty);
        _items.Add((sku, price, qty));
    }

    public bool RemoveItem(string sku) =>
        _items.RemoveAll(i => i.Sku == sku) > 0;

    public bool ApplyPromoCode(string code)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(code);
        if (_promoCodes.TryGetValue(code, out var discount))
        {
            _discount = discount;
            return true;
        }
        return false;
    }

    public decimal GetTotal()
    {
        var subtotal = _items.Sum(i => i.Price * i.Qty);
        return subtotal - (subtotal * _discount);
    }
}

