using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_AppearsInItems()
    {
        _cart.AddItem("SKU-1", 9.99m, 2);

        var item = Assert.ContainsSingle(_cart.Items);
        Assert.AreEqual("SKU-1", item.Sku);
        Assert.AreEqual(9.99m, item.Price);
        Assert.AreEqual(2, item.Qty);
    }

    [TestMethod]
    public void AddItem_MultipleItems_AllAppear()
    {
        _cart.AddItem("A", 5m, 1);
        _cart.AddItem("B", 10m, 3);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    public void AddItem_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(null!, 10m, 1));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", 0m, 1));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", 5m, 0));
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU-1", 10m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-1"));
        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_RemovesDuplicateSkus()
    {
        _cart.AddItem("SKU-1", 5m, 1);
        _cart.AddItem("SKU-1", 5m, 2);

        _cart.RemoveItem("SKU-1");

        Assert.IsEmpty(_cart.Items);
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow(10.00, 1, 10.00)]
    [DataRow(5.50, 3, 16.50)]
    [DataRow(99.99, 2, 199.98)]
    public void GetTotal_SingleItem_ReturnsPriceTimesQty(
        double price, int qty, double expected)
    {
        _cart.AddItem("X", (decimal)price, qty);

        Assert.AreEqual((decimal)expected, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 10m, 2); // 20
        _cart.AddItem("B", 5m, 3);  // 15

        Assert.AreEqual(35m, _cart.GetTotal());
    }

    // --- ApplyPromoCode ---

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyPromoCode_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("X", 100m, 1);

        Assert.IsTrue(_cart.ApplyPromoCode(code));
        Assert.AreEqual((decimal)expectedTotal, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive_Works()
    {
        _cart.AddItem("X", 100m, 1);

        Assert.IsTrue(_cart.ApplyPromoCode("save10"));
        Assert.AreEqual(90m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_DoesNotAffectTotal()
    {
        _cart.AddItem("X", 50m, 2);

        _cart.ApplyPromoCode("BOGUS");

        Assert.AreEqual(100m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_NullCode_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyPromoCode(null!));
    }

    [TestMethod]
    public void ApplyPromoCode_SecondCodeOverridesFirst()
    {
        _cart.AddItem("X", 100m, 1);

        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");

        Assert.AreEqual(80m, _cart.GetTotal());
    }
}

